// Shopify кладёт заказ в body. Собираем короткое человеческое уведомление.
const o = $input.first().json.body || $input.first().json;
const items = (o.line_items || []).map((i) => `${i.title} ×${i.quantity}`).join(', ');
const country = (o.shipping_address && o.shipping_address.country_code) || '';
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const tgLines = [
  `🛒 <b>Новый заказ ${esc(o.name || '')}</b>`,
  `${esc(o.total_price || '?')} ${esc(o.currency || '')}${country ? ' · ' + esc(country) : ''}`,
  ...(o.line_items || []).map((i) => `• ${esc(i.title)} ×${i.quantity}`),
];
return [{ json: {
  kind: 'order',
  title: `Новый заказ ${o.name || ''}`.trim(),
  text: [`${o.total_price || '?'} ${o.currency || ''}`.trim(), country, items].filter(Boolean).join(' · '),
  order: o.name || null,
  created_at: o.created_at || null,
  telegram_text: tgLines.join('\n'),
  telegram_on: Boolean($env.TELEGRAM_BOT_TOKEN && $env.TELEGRAM_CHAT_ID),
} }];
